package com.autoops.command.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="command_definitions") public class CommandDefinition { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String name; private String description; private String category; private String action; @Column(name="resource_type") private String resourceType; @Column(name="command_template",nullable=false,columnDefinition="text") private String commandTemplate; @Column(name="risk_level",nullable=false) private String riskLevel="LOW"; @Column(nullable=false) private String status="PENDING"; @Column(nullable=false) private String source="USER"; @Column(name="created_by",nullable=false) private Long createdBy; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getCommandTemplate(){return commandTemplate;} public void setCommandTemplate(String v){commandTemplate=v;} public String getRiskLevel(){return riskLevel;} public void setRiskLevel(String v){riskLevel=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public Long getCreatedBy(){return createdBy;} public void setCreatedBy(Long v){createdBy=v;} }
